if(mode==9)return spots(q*vec2(n,n*.5)+vec2(0,-t)+h,r*.06,.01)*y*exp(-abs(x)/width);
if(mode==10)return line(length(q-vec2(-r,0))-r,w,.02)*fill(abs(q.y)-r,.02)*y;
if(mode==11)return max(max(exp(-abs(x-width*.5)/w),exp(-abs(x)/w)),exp(-abs(x+width*.5)/w))*pow(y,2.);
if(mode==12)return exp(-abs(x-k*.2*sin(q.y*n-t))/max(w*4.,.01))*y;
if(mode==13)return base*(.5+.5*sin(q.y*n*TAU+abs(x)*n-t))*y;
