if(mode<4.5)return outer+polygon+line(poly(rot(q,PI/max(3.,n)),max(3.,n),r*.65),w,s);
if(mode<5.5)return outer+line(poly(q,3.,r*.7),w,s)+line(poly(-q,3.,r*.7),w,s);
if(mode<6.5)return outer+line(box(q,vec2(r*.5),0.),w,s)+line(box(rot(q,PI/4.),vec2(r*.5),0.),w,s);
if(mode<7.5)return line(sin(rad*n*PI),w*2.,s)*fill(rad-r,s)+ticks;
